"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["65377"],{44321(e,i,t){t.r(i),t.d(i,{metadata:()=>n,default:()=>p,frontMatter:()=>a,contentTitle:()=>r,toc:()=>h,assets:()=>l});var n=JSON.parse('{"id":"tianya/beijinghouseprice","title":"","description":"I previously wrote a post about the real estate market becoming stock-market-like. But an important characteristic of stock-market-ification is the differentiation of individual stocks. Even in a bear market, there are stocks hitting new highs -- the real estate market is the same. Beijing is precisely such a stock. Regardless of what happens in other cities, Beijing housing prices have no possibility of declining.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tianya/beijinghouseprice.md","sourceDirName":"tianya","slug":"/tianya/beijinghouseprice","permalink":"/en/tianya/beijinghouseprice","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"beijinghouseprice","title":"","hide_table_of_contents":true,"sidebar_label":"Regardless of other cities, Beijing\'s housing prices have no possibility of declining"},"sidebar":"tianyaSidebar","previous":{"title":"Gigolo establishments \u2014 the most important marker of a city and nation\'s civilizational progress!","permalink":"/en/tianya/duckstore"},"next":{"title":"This lady\'s arrival has greatly elevated the taste and sophistication here!","permalink":"/en/tianya/mypresence"}}'),s=t(74848),o=t(28453);let a={id:"beijinghouseprice",title:"",hide_table_of_contents:!0,sidebar_label:"Regardless of other cities, Beijing's housing prices have no possibility of declining"},r="Regardless of What Happens in Other Cities, Beijing Housing Prices Have No Possibility of Declining.",l={},h=[];function c(e){let i={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(i.header,{children:(0,s.jsx)(i.h1,{id:"regardless-of-what-happens-in-other-cities-beijing-housing-prices-have-no-possibility-of-declining",children:"Regardless of What Happens in Other Cities, Beijing Housing Prices Have No Possibility of Declining."})}),"\n",(0,s.jsx)(i.p,{children:"I previously wrote a post about the real estate market becoming stock-market-like. But an important characteristic of stock-market-ification is the differentiation of individual stocks. Even in a bear market, there are stocks hitting new highs -- the real estate market is the same. Beijing is precisely such a stock. Regardless of what happens in other cities, Beijing housing prices have no possibility of declining."}),"\n",(0,s.jsx)(i.p,{children:"This lady lives near the Second Ring Road. Never mind the Second Ring -- if you're on the east or north side, there are barely any plots left to build on even near the Fourth Ring. This lady has bought properties in no fewer than one location. In other places, few people pay in full like this lady does. But in Beijing there are plenty. At least where I currently live, most people pay in full at once. Beijing's high-end properties never worry about finding buyers."}),"\n",(0,s.jsx)(i.p,{children:"As for Beijing's demolition compensation prices, they're also absurdly high. Other places probably haven't seen demolition prices of over 10,000 yuan per square meter. Many original city residents, after receiving demolition compensation, go to a slightly more distant area and buy a much larger apartment with money left over. Due to these people and the hordes fighting to get into Beijing, even apartments in Tongzhou can't possibly be too cheap. There's basically no downside room, and the buying support is staggering."}),"\n",(0,s.jsx)(i.p,{children:"Moreover, Beijing's housing prices aren't expensive at all compared to other places like Jiangsu-Zhejiang or Qingdao. Once a real estate company invited me to Qingdao and told me that buildings near the Olympic sailing venue by the sea were all above 20,000/sqm. Then they went to a relatively remote area, pointed at some small run-down buildings and said: \"Look, these still cost 10,000!\" By comparison, Beijing's housing is practically too cheap: for instance, within 200 meters of the main Olympic venue, there are buildings at 7,000/sqm."}),"\n",(0,s.jsx)(i.p,{children:"Let price cuts happen elsewhere -- around the Olympics, Beijing's housing won't drop. As for stock commentators and housing commentators -- they can say whatever they want. How could capable people possibly become stock commentators or housing commentators? Economic history has proven countless times: stock commentators, housing commentators, and prophets all end up as jokes."}),"\n",(0,s.jsx)(i.p,{children:"Declaration: All properties this lady has purchased are for personal residence. I have never owed a bank a single cent. The above views have nothing to do with any private interests."})]})}function p(e={}){let{wrapper:i}={...(0,o.R)(),...e.components};return i?(0,s.jsx)(i,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},28453(e,i,t){t.d(i,{R:()=>a,x:()=>r});var n=t(96540);let s={},o=n.createContext(s);function a(e){let i=n.useContext(o);return n.useMemo(function(){return"function"==typeof e?e(i):{...i,...e}},[i,e])}function r(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),n.createElement(o.Provider,{value:i},e.children)}}}]);